if(sty==='koi'){ bodyc=[0,0,100]; bel=[0,0,100]; finc=[15,70,100]; stripec=[15,85,90]; eyeR=[0,0,10]; }
else if(sty==='neon'){ bodyc=[P.hue,30,25]; bel=[P.hue,30,25]; finc=[(P.hue+160)%360,90,100]; stripec=[(P.hue+160)%360,90,100]; eyeR=[(P.hue+160)%360,90,100]; glow=true; }
else if(sty==='xray'){ bodyc=[P.hue,20,30]; bel=[P.hue,20,30]; finc=[P.hue,15,45]; stripec=[P.hue,10,70]; eyeR=[0,0,100]; }
else if(sty==='angel'){ bodyc=[50,20,100]; bel=[50,10,100]; finc=[45,70,100]; stripec=[210,30,20]; eyeR=[0,0,10]; }
function Cc(a,al){ return color(a[0],a[1],a[2],(al==null?100:al)*P.alpha/100); }

// bubbles behind
if(P.bubbles>0.05){ noStroke(); for(let i=0;i<P.bubbles*16;i++){ const life=(t*0.3+fr(i))%1; const bx=cx-40*sc-fr(i+3)*40*sc; const by=cy - life*180*sc + Math.sin(t+i)*6; fill(Cc([P.hue,20,100], (1-life)*35)); circle(bx,by,(2+fr(i+7)*4)*sc*(0.5+life*0.5)); } }

push();
translate(cx+swimX, cy+swimY);
scale(dir*sc, sc);
rotate(Math.sin(t*0.5)*0.06);
if(glow){ dc.shadowBlur=18; dc.shadowColor=Cc(finc,80).toString(); }

// tail
fill(Cc(finc,100));
push(); translate(-46,0); rotate(tailW*0.3);
beginShape(); vertex(0,0); vertex(-30,-24-P.fins*10); vertex(-22,0); vertex(-30,24+P.fins*10); endShape(CLOSE); pop();
