beginShape(); vertex(-6,-24); bezierVertex(4,-44-fw*8, 24,-30, 20,-18); endShape(CLOSE);
beginShape(); vertex(-6,24); bezierVertex(2,40+fw*8, 20,30, 18,18); endShape(CLOSE);
// body
fill(Cc(bodyc,100));
beginShape(); vertex(-44,0); bezierVertex(-30,-30,20,-32,44,-6); bezierVertex(50,-2,50,2,44,6); bezierVertex(20,32,-30,30,-44,0); endShape(CLOSE);
// belly
