// stripes
if(P.stripes>0.05 && sty!=='xray'){ dc.save(); dc.beginPath(); dc.ellipse(0,0,46,30,0,0,TAU); dc.clip();
  const ns=Math.floor(2+P.stripes*6); stroke(Cc(stripec,80)); strokeWeight(4+P.stripes*4); noFill();
  for(let i=0;i<ns;i++){ const x=-30+i*(64/ns) + Math.sin(t+i)*2; line(x,-30,x-8,30); } dc.restore(); noStroke(); }
// xray ribs
if(sty==='xray'){ stroke(Cc([P.hue,20,80],70)); strokeWeight(1.4); noFill(); for(let i=0;i<7;i++){ const x=-24+i*8; arc(x,4,10,34,Math.PI*0.5,Math.PI*1.5);} noStroke(); }
